// Verilator simulation core shared by every compiled testbench (test/common/verilator.py).
//
// A Sim owns the Verilated top (V<top>), its signals by name (the table generated by
// verilator.py from the Migen ios), its memories by name (DUT memories made public by the
// generated .vlt, and the memories of the C++ models) and the models (AXI slaves,
// scratchpad clients) that answer the DUT every cycle.
//
// One cycle: settle() lets every model drive its inputs from its state and evaluates the
// DUT; tick() settles, lets every model sample the cycle's handshakes, then clocks the
// rising edge. A testbench reads outputs between settle() and tick(), as the hardware
// would at the edge. The cycle cap turns a hang into a clean error.

#pragma once

#include <cstdarg>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <functional>
#include <iterator>
#include <map>
#include <string>
#include <vector>

#include "verilated.h"

// Errors -------------------------------------------------------------------------------------------

static std::function<void()> sim_on_fail;  // Diagnostics hook (the script's dump list).
static std::function<void()> sim_on_exit;  // Closes the waveform (flushed even on a failure).

[[noreturn]] static void sim_fail(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    std::fprintf(stderr, "error: ");
    std::vfprintf(stderr, fmt, ap);
    std::fprintf(stderr, "\n");
    va_end(ap);
    if (sim_on_fail) {
        auto hook = sim_on_fail;
        sim_on_fail = nullptr;
        hook();
    }
    if (sim_on_exit) sim_on_exit();
    std::fflush(stdout);
    std::fflush(stderr);
    std::exit(2);
}

static void sim_require(bool ok, const char *what) { if (!ok) sim_fail("%s", what); }

// Files --------------------------------------------------------------------------------------------

static std::vector<uint8_t> sim_load(const std::string &path) {
    std::ifstream f(path, std::ios::binary);
    if (!f) sim_fail("cannot open %s", path.c_str());
    return std::vector<uint8_t>((std::istreambuf_iterator<char>(f)), {});
}

static void sim_save(const std::string &path, const uint8_t *data, size_t len) {
    std::ofstream f(path, std::ios::binary);
    if (!f) sim_fail("cannot write %s", path.c_str());
    f.write(reinterpret_cast<const char *>(data), len);
}

// Random -------------------------------------------------------------------------------------------

struct SimRandom {
    uint64_t state;
    explicit SimRandom(uint64_t seed = 1) : state(seed*0x9E3779B97F4A7C15ull + 1) {}
    uint32_t next() {
        state ^= state << 13; state ^= state >> 7; state ^= state << 17;
        return (uint32_t)(state >> 16);
    }
    bool percent(uint32_t pct) { return pct && (next() % 100) < pct; }
};

// Signals ------------------------------------------------------------------------------------------

struct Sig {
    std::string name;
    int      width = 0;
    int      bytes = 0;     // Storage: 1/2/4/8 (CData..QData), or 0 for VlWide (32-bit words).
    void    *p     = nullptr;

    int words() const { return (width + 31)/32; }

    uint64_t get() const {
        switch (bytes) {
        case 1: return *(uint8_t  *)p;
        case 2: return *(uint16_t *)p;
        case 4: return *(uint32_t *)p;
        case 8: return *(uint64_t *)p;
        default: { const uint32_t *w = (const uint32_t *)p;
                   return w[0] | (words() > 1 ? (uint64_t)w[1] << 32 : 0); }
        }
    }
    void set(uint64_t v) {
        if (width < 64) v &= (1ull << width) - 1;
        switch (bytes) {
        case 1: *(uint8_t  *)p = (uint8_t)v;  break;
        case 2: *(uint16_t *)p = (uint16_t)v; break;
        case 4: *(uint32_t *)p = (uint32_t)v; break;
        case 8: *(uint64_t *)p = v;           break;
        default: { uint32_t *w = (uint32_t *)p;
                   std::memset(w, 0, 4*words());
                   w[0] = (uint32_t)v; if (words() > 1) w[1] = (uint32_t)(v >> 32); }
        }
    }
    void get_words(uint32_t *out) const {
        if (bytes) { uint64_t v = get(); out[0] = (uint32_t)v; if (words() > 1) out[1] = (uint32_t)(v >> 32); }
        else std::memcpy(out, p, 4*words());
    }
    void set_words(const uint32_t *in) {
        if (bytes) set(in[0] | (words() > 1 ? (uint64_t)in[1] << 32 : 0));
        else {
            std::memcpy(p, in, 4*words());
            if (width % 32) ((uint32_t *)p)[words() - 1] &= (1u << (width % 32)) - 1;
        }
    }
    std::string hex() const {
        std::vector<uint32_t> w(words());
        get_words(w.data());
        std::string s;
        char buf[16];
        bool lead = true;
        for (int i = words() - 1; i >= 0; i--) {
            std::snprintf(buf, sizeof(buf), lead ? "%x" : "%08x", w[i]);
            if (!lead || w[i] || i == 0) { s += buf; lead = false; }
        }
        return s;
    }
};

// Memories -----------------------------------------------------------------------------------------
// Byte-addressed views of a word memory (little-endian words of `width` bits, width % 8 == 0).

struct Mem {
    std::string name;
    size_t      size = 0;     // Bytes.
    std::function<void(size_t, uint8_t *, size_t)>       read;  // (addr, out, len)
    std::function<void(size_t, const uint8_t *, size_t)> write; // (addr, in,  len)
};

// A DUT memory made public by the .vlt: VlUnpacked<VlWide<N>, depth> or narrower elements.
template <typename A>
static Mem sim_dut_memory(const std::string &name, A *arr, size_t width, size_t depth) {
    Mem m;
    size_t wb = width/8;
    m.name = name;
    m.size = wb*depth;
    m.read = [arr, wb](size_t addr, uint8_t *out, size_t len) {
        for (size_t i = 0; i < len; i++) {
            size_t a = addr + i;
            const auto &e = (*arr)[a/wb];
            out[i] = reinterpret_cast<const uint8_t *>(&e)[a % wb];
        }
    };
    m.write = [arr, wb](size_t addr, const uint8_t *in, size_t len) {
        for (size_t i = 0; i < len; i++) {
            size_t a = addr + i;
            auto &e = (*arr)[a/wb];
            reinterpret_cast<uint8_t *>(&e)[a % wb] = in[i];
        }
    };
    return m;
}

// A plain byte vector owned by a model (AXI slave memory, scratchpad image).
static Mem sim_vector_memory(const std::string &name, std::vector<uint8_t> *v) {
    Mem m;
    m.name  = name;
    m.size  = v->size();
    m.read  = [v](size_t addr, uint8_t *out, size_t len) { std::memcpy(out, v->data() + addr, len); };
    m.write = [v](size_t addr, const uint8_t *in, size_t len) { std::memcpy(v->data() + addr, in, len); };
    return m;
}

// Models -------------------------------------------------------------------------------------------

struct Sim;

struct Model {
    virtual ~Model() {}
    virtual void drive(Sim &sim) = 0;                 // Set DUT inputs from the model's state.
    virtual void sample(Sim &sim) = 0;                // Take this cycle's handshakes (before the edge).
    virtual void report(Sim &) {}                     // End-of-run statistics.
};

// Sim ----------------------------------------------------------------------------------------------

struct Sim {
    VerilatedContext           *ctx = nullptr;
    std::function<void(int)>    clock;     // Drives sys_clk.
    std::function<void()>       eval;
    std::function<void(uint64_t)> dump;  // Waveform sample (tracing builds only, see sim_bind).
    std::map<std::string, Sig>  sigs;
    std::map<std::string, Mem>  mems;
    std::vector<Model *>        models;
    std::vector<std::function<void()>> on_cycle; // Called once per cycle, settled, before the edge.
    uint64_t cycle      = 0;
    uint64_t max_cycles = 50000000;
    bool     settled    = false; // Inputs unchanged since the last settle(): tick() skips it.

    Sig *find(const std::string &name) {
        auto it = sigs.find(name);
        return it == sigs.end() ? nullptr : &it->second;
    }
    Sig &sig(const std::string &name) {
        Sig *s = find(name);
        if (!s) sim_fail("no signal '%s' (add it to the ios)", name.c_str());
        return *s;
    }
    Mem &mem(const std::string &name) {
        auto it = mems.find(name);
        if (it == mems.end()) sim_fail("no memory '%s'", name.c_str());
        return it->second;
    }

    template <typename T> void add(const std::string &name, int width, T *p) {
        Sig s; s.name = name; s.width = width; s.bytes = sizeof(T) <= 8 ? (int)sizeof(T) : 0; s.p = (void *)p;
        sigs[name] = s;
    }
    void add_memory(const Mem &m) { mems[m.name] = m; }

    void settle() {
        for (auto *m : models) m->drive(*this);
        eval();
        if (dump) dump(2*cycle);
        settled = true;
    }
    void tick() {
        if (!settled) settle();
        for (auto &f : on_cycle) f();
        for (auto *m : models) m->sample(*this);
        clock(1);
        eval();
        if (dump) dump(2*cycle + 1);
        clock(0);
        settled = false;
        cycle++;
        if (cycle > max_cycles)
            sim_fail("cycle cap reached (%llu cycles)", (unsigned long long)max_cycles);
    }
    void finish() {
        if (sim_on_exit) { sim_on_exit(); sim_on_exit = nullptr; }
    }
    void reset(int cycles = 2) {
        Sig *rst = find("sys_rst");
        if (rst) rst->set(1);
        settled = false;
        for (int i = 0; i < cycles; i++) tick();
        if (rst) rst->set(0);
    }
};
